parameters.jsCode:
const rows = $input.all();
let hist = '';
for (const r of rows) {
  const u = (r.json.mensagem_usuario || '').trim();
  const a = (r.json.mensagem_agente || '').trim();
  if (u) hist += 'Lead: ' + u + '\n';
  if (a) hist += 'SDR: ' + a + '\n';
}
return { json: { historico: hist, telefone: $('Loop Over Items').item.json.telefone } };

parameters.query:
insert into mailing_snapshot (telefone, last_chars, updated_at)
values ('{{ $('Formata Histórico').first().json.telefone }}', {{ $('Loop Over Items').first().json.chars_atual }}, now())
on conflict (telefone) do update set last_chars = excluded.last_chars, updated_at = now();

